import {GOODS,CHAPTERS,LEVEL_COUNT} from './content.js';
import {shelfSpaces,shelfMoves,puzzleSpec,nextPuzzle} from './shelf-engine.js';
export function shelfBoard(state,selected,hintMove,good,highlighted=[]){
  return state.shelves.map((s,si)=>{
    const back=s.rows[1]||[],backCount=s.rows.slice(1).flat().filter(t=>t!==null).length;
    const gate=s.lock?`<button class="shelf-key" data-key-help="${si}" aria-label="Shelf ${si+1} is locked. Match three ${GOODS[s.key].name.toLowerCase()} on an open shelf to unlock it.">${good(s.key)}<span>Match 3<br><b>${GOODS[s.key].short}</b></span><span aria-hidden="true">🔒</span></button>`:'';
    return `<div class="shelf ${s.lock?'locked':''}" data-shelf="${si}" aria-label="Shelf ${si+1}${s.lock?', locked':''}${backCount?`, ${backCount} goods behind`:''}">${backCount?`<div class="backstock">${back.map(t=>t===null?'<span></span>':good(t)).join('')}</div><span class="shelf-stock-number" aria-hidden="true">+${backCount}</span>`:''}<div class="shelf-items">${s.rows[0].map((t,slot)=>{
      const picked=selected?.shelf===si&&selected?.slot===slot;
      const source=hintMove?.[0]===si&&hintMove?.[1]===slot||highlighted.some(p=>p.shelf===si&&p.slot===slot),destination=hintMove?.[2]===si&&hintMove?.[3]===slot;
      return `<button class="item ${t===null?'open-slot':''} ${picked?'selected-good':''} ${source?'hinted':''} ${destination?'hint-destination':''} ${selected&&t===null&&si!==selected.shelf?'can-place':''}" data-shelf="${si}" data-slot="${slot}" ${t!==null?`data-type="${t}" data-short="${GOODS[t].short}"`:''} aria-label="${t===null?'Empty space':GOODS[t].name}, shelf ${si+1}, position ${slot+1}" ${t!==null?`aria-pressed="${picked}"`:''} ${s.lock||state.status!=='playing'?'disabled':''}>${t===null?'<span class="slot-mark" aria-hidden="true">＋</span>':good(t)}${destination?'<span class="place-here">here</span>':''}</button>`;
    }).join('')}</div>${gate}<button class="shelf-label stock-preview-button" data-stock-preview="${si}" aria-label="Inspect shelf ${si+1}, ${backCount} goods behind">${String(si+1).padStart(2,'0')}${backCount?' · peek':s.rows[0].every(t=>t===null)?' · clear':' · front row'}</button></div>`;
  }).join('');
}
export function shelfStatus(state,selected,thinking=false){
  const free=shelfSpaces(state.shelves),blocked=state.status==='playing'&&!shelfMoves(state.shelves).length;
  return `<div class="puzzle-stats"><span><strong>${state.moves}</strong> ${state.moves===1?'move':'moves'}</span><span>Target <strong>${state.spec.target}</strong></span><span class="${free<2?'space-tight':''}"><strong>${free}</strong> free ${free===1?'space':'spaces'}</span></div><p class="puzzle-instruction" aria-live="polite">${thinking?'Looking a few moves ahead…':blocked?'No legal moves. Undo a move or restart this puzzle.':selected?`${GOODS[state.shelves[selected.shelf].rows[0][selected.slot]].name} selected. Tap an empty space on another shelf.`:'Tap a good, then an empty space. Three together on one shelf clear.'}</p>`;
}
export function shelfMap(profile,state,chapter=0){
  const ch=CHAPTERS[chapter],first=chapter*50+1,next=nextPuzzle(profile),resume=state.mode==='puzzle'?state:profile.sessions.puzzle?.state;
  return `<div class="modal-eyebrow">${LEVEL_COUNT} SHELF PUZZLES · NO TIMER</div><h2 class="modal-title" id="modal-title">A few moves ahead.</h2><p class="modal-copy">${profile.puzzleWins} / ${LEVEL_COUNT} solved · ${profile.puzzleStars} / ${(LEVEL_COUNT*3).toLocaleString('en-US')} stars. Tight spaces, buried stock, and matches that open the way.</p><button class="primary-button" ${resume?.moves&&resume.status==='playing'?'data-action="resume-puzzle"':`data-puzzle-level="${next}"`}>${resume?.moves&&resume.status==='playing'?`Resume puzzle ${resume.levelId}`:`Continue at ${next}`} →</button><div class="chapter-scroll" aria-label="Shelf puzzle chapters">${CHAPTERS.map((c,i)=>`<button class="chapter-button ${i===chapter?'active':''}" data-puzzle-chapter="${i}" aria-label="Shelf chapter ${i+1}: ${c.name}" aria-pressed="${i===chapter}"><span aria-hidden="true">${c.icon}</span>${i*50+1}–${(i+1)*50}</button>`).join('')}</div><div class="chapter-heading"><h3>${ch.name}</h3><small>${Array.from({length:50},(_,i)=>profile.puzzles[first+i]).filter(Boolean).length} / 50 solved</small></div><p class="modal-copy compact">${chapter<2?'One keyed shelf. Make room before you match.':chapter<4?'Two keyed shelves. Decide which match opens your route.':'Eight shelves. More buried stock and interlocking keys.'}</p><div class="level-grid">${Array.from({length:50},(_,i)=>{const id=first+i,p=puzzleSpec(id),r=profile.puzzles[id];return `<button class="level-button ${r?'complete':''} ${id===next?'current':''}" data-puzzle-level="${id}" aria-label="Puzzle ${id}, target ${p.target} moves${r?`, ${r.stars} stars`:''}"><strong>${id}</strong><small>${p.target} moves</small><small aria-hidden="true">${'★'.repeat(r?.stars||0)}${'☆'.repeat(3-(r?.stars||0))}</small></button>`;}).join('')}</div><div class="trail-jump"><span>★ Solve · ★ No hints · ★ Within target</span><label>Jump to <input id="puzzle-jump" type="number" min="1" max="${LEVEL_COUNT}" value="${next}" aria-label="Puzzle number"><button data-action="puzzle-jump">Go</button></label></div><p class="modal-copy compact">Targets come from checked solutions. They are beatable benchmarks, not claims of the fewest possible moves. Your old basket Trail has its own records in Other modes.</p><button class="secondary-button" data-action="close">Back to the shelves</button>`;
}
